import{_ as e,c as a,a2 as t,o as r}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"“该批评”的时候不批评，“不该批评”的时候批评","description":"","frontmatter":{},"headers":[],"relativePath":"技能/批评教育小孩.md","filePath":"技能/批评教育小孩.md"}'),o={name:"技能/批评教育小孩.md"};function n(s,p,c,i,_,d){return r(),a("div",null,p[0]||(p[0]=[t('<h1 id="该批评-的时候不批评-不该批评-的时候批评" tabindex="-1">“该批评”的时候不批评，“不该批评”的时候批评 <a class="header-anchor" href="#该批评-的时候不批评-不该批评-的时候批评" aria-label="Permalink to &quot;“该批评”的时候不批评，“不该批评”的时候批评&quot;">​</a></h1><p>因为你很可能违反了原则：“该批评”的时候不批评，“不该批评”的时候批评。</p><p>这个“原则”是我总结的育儿原则，尤其是幼儿。</p><p>“该批评”的时候不批评：</p><p>幼儿和小学生犯错有几种情况：</p><p>无意识犯错，比如题主说的把水打翻 想引起关注的犯错，比如墙上乱画，比如在爸爸鞋里撒尿 好奇或觉得好玩，比如把沙发扣个洞，但他并不知道沙发有多贵，他觉得就像他把玩具车轮子拧下来是一样的 这些都是看上去“该批评”的，但其实不要批评，或者批评会没有结果或更坏的结果：</p><p>无意识犯错，为何要批评他？ 想引起关注，你批评他，岂不是让他继续，最好的方法是装作不知道，让他觉得这样做没趣，然后他就不做了 好奇心不是很多人说的要保护的吗？ “不该批评”的时候批评：</p><p>许多事情，看似不严重，但最终会形成难以改变的习惯，而最初在幼儿或少年时代是很容易纠正的，这些事情，家长就一定要识别出来，要详细地给他解释，要严厉地纠正：</p><p>不专注，玩任何东西都东一下西一下，一会儿干这一会儿干那 不负责，已经明确应该他做的事情随意地不做 不坚持，想到要学什么就学什么，稍微遇到困难或感觉枯燥就放弃 不思考，走迷宫、猜谜语、找不同等游戏，稍难就放弃 不总结，不断犯一模一样的错误 如果识别出这“五不”，就要详细地给他说明，要让他知道问题很严重，必要时严厉批评甚至惩罚，最终一定要培养好五个习惯。</p><p>因为前面的“该批评”的时候不批评，他对家长的批评就不容易形成“抗药性”，就很容易接受“不该批评”的时候批评。</p><p>如果有了这五个好习惯，他以后的学习和生活还要担心吗？</p><p>知友评论很多，我一一仔细看了，有些确实是我写得太简略导致的，因此补充说明一下：</p><p>这是我自己经验的分享，没有任何卖课或其他企图（何况我也没有可卖的）。我确实是这样的理念，也是这样做的，自认效果不错：我儿子高考700+。 确实不一定能适用于所有孩子，但我觉得理念是适用的，具体执行要看具体情况。这也是我一直的教育理念。我当年也会接触到各种他人秘籍和经验，但我都会思考其底层逻辑，从最基本的思维方式去借鉴别人好的东西，而不是去学“方法”——方法因人而异，但理念相同。 我文章要表达的核心是：家长要想办法控制自己的情绪，要根据情况判断是不是要训他，而不是跟着我们自己的情绪走。因为我们训他的底层思维是要培养他的习惯和正确的三观，而不是为了当前的一件事。这很难，但我觉得是值得的，尤其是孩子很小的时候这么做（12岁之前），会培养出很好的习惯和三观，以后家长会极度轻松。反之，一旦孩子大了，再去纠正习惯和三观是非常困难的，很累且效果微弱。 许多人觉得孩子难搞，但我坚定地认为：12岁以下的孩子的情绪和心思很容易观察到（更小时更容易），只看家长是否用心，用心观察，用心去“管”和“培养”，其实不难。但很多家长喜欢简单地“控制”，喜欢简单地“管教”。当时简单，以后麻烦。 文章没有说年龄，是我写的不严谨，在回答评论时我多次强调不同年龄段不同对待，但底层逻辑是一样的，比如说孩子读初中了，他无意识的错误可能变成了作文跑题，他求关注的错误可能变成了故意与家长顶着来…… 题主没有说骂孩子，而孩子哭着不愿意擦干水。确实如此。题主也没有说孩子的年龄。但我的经验是：如果很平常地说话，比如说：“我们赶快把水擦干吧，不然等会你或妈妈滑倒就麻烦了，我手腾不开，你去擦好吗？”，孩子大概率不会哭着拒绝，不管多大。 我说的“不负责”，指的是没有责任心，或者说明知是他自己的事情或自己承诺的事情，很随意地放弃或不做。这个很危险，我至少见过三个孩子的案例：初二，很随意地找理由下午不去上学，最后甚至理由都不找，就是不想去。很随意地考试不写作文，理由刚开始是没时间，后来就是不想写……</p>',13)]))}const f=e(o,[["render",n]]);export{m as __pageData,f as default};
